/**
 * The trial-end screen (sales plan A, 2026-10-24): one full screen, once,
 * on the first open of Today after the trial ends, and once on the trial's
 * last day if the app is opened then. What Pro did (the server's counts),
 * the open offer with its real countdown, the honest anchors, a way to
 * invite friends, and "Continue with Free".
 *
 * Separate from the campaign's full-screen offer (`campaign.ts` and its own
 * caps): this one belongs to the trial and is remembered per trial in meta
 * `trialNotes` (`endScreen`, `lastDayScreen`). It keeps every silence of
 * Today's trial moments: only where the server lets Today speak of the
 * trial (`touches`, which "Don't remind me" turns off), only where Pro may
 * be sold on this client and in this notebook (`trialVoiced`: never in the
 * desktop app, which cannot sell), never to a payer, and never beside a
 * celebration on the same visit (the screen waits for the next one). Pure:
 * the caller passes the plan, the clock and what this device remembers.
 */
import type { ApiBillingState, ApiOfferEventInput } from '@/api/types.js';
import type { StoredTrialNotes } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import type { PlanLimits } from '@/lib/useConfig.js';
import { paidPlan, trialDaysLeft } from './offer.js';
import { endedTrial, runningTrial, TRIAL_END_CARD_DAYS } from './trial.js';

const DAY_MS = 86_400_000;

/** Which screen: after the end, or on the last day. `key` is the trial it is remembered by. */
export interface TrialEndMoment {
  kind: 'ended' | 'last';
  key: string;
}

export interface TrialEndSignals {
  now: Date;
  notes: StoredTrialNotes;
  /** `trialVoiced` for the notebook in view. */
  voiced: boolean;
  /** A celebration has this visit: the screen waits, unspent. */
  celebrating: boolean;
  /** Only for tests, to pin a time zone; a screen passes none and gets the learner's own. */
  zone?: string | undefined;
}

/** The trial-end screen this visit should open, or undefined. */
export function trialEndScreen(
  state: ApiBillingState | null,
  signals: TrialEndSignals,
): TrialEndMoment | undefined {
  if (state === null || !signals.voiced || signals.celebrating || paidPlan(state)) return undefined;
  const { notes, now } = signals;

  const ended = endedTrial(state);
  if (ended !== undefined) {
    if (!ended.touches || notes.endScreen === ended.key) return undefined;
    // Somebody back long after has not "just" come out of a trial.
    if (now.getTime() - ended.endedAt.getTime() > TRIAL_END_CARD_DAYS * DAY_MS) return undefined;
    return { kind: 'ended', key: ended.key };
  }

  const running = runningTrial(state, now);
  if (!running?.touches) return undefined;
  if (trialDaysLeft(running.endsAt, now, signals.zone) !== 0 || notes.lastDayScreen === running.key)
    return undefined;
  return { kind: 'last', key: running.key };
}

/** The notes after the screen was shown. */
export function noteTrialEndScreen(notes: StoredTrialNotes, moment: TrialEndMoment): StoredTrialNotes {
  return moment.kind === 'ended'
    ? { ...notes, endScreen: moment.key }
    : { ...notes, lastDayScreen: moment.key };
}

/** The four answers to "Why not now?", in the order shown (the contract's enum). */
export const DISMISS_REASONS = ['too_expensive', 'no_need', 'cant_pay', 'later'] as const;

export type DismissReason = NonNullable<ApiOfferEventInput['reason']>;

/** Whether a value is one of the contract's answers. */
export function isDismissReason(value: unknown): value is DismissReason {
  return (DISMISS_REASONS as readonly unknown[]).includes(value);
}

/**
 * The extra fields of an offer event: `reason` only on `dismissed` and
 * only when it is one of the contract's answers; the server refuses it
 * anywhere else, so it is never sent anywhere else.
 */
export function offerEventExtra(
  event: ApiOfferEventInput['event'],
  extra: Omit<ApiOfferEventInput, 'event' | 'surface' | 'reason'>,
  reason?: unknown,
): Omit<ApiOfferEventInput, 'event' | 'surface'> {
  return event === 'dismissed' && isDismissReason(reason) ? { ...extra, reason } : { ...extra };
}

/**
 * What Free leaves out, by name, in the server's numbers (`GET /config`
 * `limits`), for the trial's last days: "no Lex", "no voice input", "125
 * fewer AI cards a day (150 on Pro, 25 on Free)". Lex is named only when
 * the server gives Free none; the AI cards with numbers only when it sent
 * both, else in words. Voice input is part of Pro on every client (the
 * free plan's table says so).
 */
export function freeLosses(limits: PlanLimits): string[] {
  const lines: string[] = [];
  const freeLex = (limits.free?.lexDaily ?? 0) + (limits.free?.lexMonthly ?? 0);
  if (freeLex === 0) lines.push(t('trial.loseLex'));
  lines.push(t('trial.loseVoice'));
  const pro = limits.pro?.aiCardsDaily;
  const free = limits.free?.aiCardsDaily;
  if (pro !== undefined && free !== undefined) {
    if (pro > free) lines.push(t('trial.loseCards', { fewer: pro - free, pro, free }));
  } else {
    lines.push(t('trial.loseCardsPlain'));
  }
  return lines;
}
